CONTACTS = [
    ("telegram", "telegram", "Telegram", "@ilovecodka"),
    ("discord", "discord", "Discord", "_ilovevodka"),
    ("steam", "steam", "Steam", "arthasfrostmorn"),
    ("site", None, "Сайт", "ilovevodkaa.github.io"),
]

SECTIONS = [("stack", "стек"), ("projects", "проекты"), ("now", "сейчас"), ("stats", "статистика")]

STACK = [
    ("языки", [("rust", "Rust"), ("csharp", "C#"), ("python", "Python"), ("java", "Java"),
               ("javascript", "JavaScript"), ("html5", "HTML"), ("css", "CSS"), ("lua", "Lua")]),
    ("движки и тулзы", [("godotengine", "Godot"), ("dotnet", ".NET"), ("git", "Git"),
                        ("telegram", "Bot API"), ("googlesheets", "Sheets"), ("claude", "Claude")]),
    ("системы", [("windows", "Windows"), ("archlinux", "Arch")]),
]


def plate(w, h, p):
    return (f'<rect x="0.5" y="0.5" width="{w - 1}" height="{h - 1}" rx="10" '
            f'fill="{p["bg"]}" stroke="{p["line"]}"/>')


def glyph(slug, x, y, size, fill):
    """Иконка simple-icons, вписанная в квадрат size с левым верхним углом (x, y)."""
    s = size / 24
    return (f'<path transform="translate({x:g} {y:g}) scale({s:.4f})" '
            f'fill="{fill}" d="{ICONS[slug][1]}"/>')


def brand_mark(x, y, size, p):
    """Знак сайта: скруглённый квадрат с полосой-подчёркиванием, как фавикон."""
    u = size / 64
    return (f'<rect x="{x:g}" y="{y:g}" width="{size:g}" height="{size:g}" rx="{14 * u:.2f}" fill="{p["ink"]}"/>'
            f'<rect x="{x + 14 * u:.2f}" y="{y + 42 * u:.2f}" width="{36 * u:.2f}" height="{7 * u:.2f}" fill="{p["bg"]}"/>')


def contact(theme, slug, title, handle):
    p = K.PALETTE[theme]
    w, h = 200, 52
    css = (K.font_css(("Inter Tight", 600), ("JetBrains Mono", 400))
           + f".n{{font:600 15px {K.SANS};fill:{p['ink']}}}"
           + f".h{{font:400 11px {K.MONO};fill:{p['muted']}}}")
    icon = glyph(slug, 16, 15, 22, p["ink"]) if slug else brand_mark(16, 15, 22, p)
    body = (plate(w, h, p) + icon
            + f'<text class="n" x="48" y="24">{K.esc(title)}</text>'
            + f'<text class="h" x="48" y="40">{K.esc(handle)}</text>'
            + f'<text class="h" x="{w - 14}" y="20" text-anchor="end">↗</text>')
    return K.svg_doc(w, h, body, f"{title}: {handle}", css)


def section(theme, idx, label, total):
    p = K.PALETTE[theme]
    w, h = 1000, 56
    text = f"( {label} )"
    size = 16
    tw = K.mono_width(text, size)
    cx, cy = w / 2, h / 2
    gap = 18
    css = (K.font_css(("JetBrains Mono", 400))
           + f".l{{font:400 {size}px {K.MONO};fill:{p['ink']}}}"
           + f".i{{font:400 12px {K.MONO};fill:{p['muted']}}}")
    left_end, right_start = cx - tw / 2 - gap, cx + tw / 2 + gap
    body = (f'<text class="i" x="0" y="{cy + 4}">{idx:02d}</text>'
            f'<line x1="34" y1="{cy}" x2="{left_end:.1f}" y2="{cy}" stroke="{p["muted"]}" stroke-opacity="0.35"/>'
            f'<text class="l" x="{cx}" y="{cy + 5.5}" text-anchor="middle">{K.esc(text)}</text>'
            f'<line x1="{right_start:.1f}" y1="{cy}" x2="{w - 34}" y2="{cy}" stroke="{p["muted"]}" stroke-opacity="0.35"/>'
            f'<text class="i" x="{w}" y="{cy + 4}" text-anchor="end">/{total:02d}</text>')
    return K.svg_doc(w, h, body, f"Раздел: {label}", css)


def stack(theme):
    p = K.PALETTE[theme]
    w = 1000
    pad, col, tile, gap, label_h, row_gap = 24, 216, 64, 18, 26, 20
    row_h = tile + label_h
    h = pad + len(STACK) * row_h + (len(STACK) - 1) * (row_gap * 2 + 1) + pad - 6
    css = (K.font_css(("JetBrains Mono", 400))
           + f".g{{font:400 13px {K.MONO};fill:{p['ink']}}}"
           + f".c{{font:400 12px {K.MONO};fill:{p['muted']}}}"
           + f".t{{font:400 11px {K.MONO};fill:{p['muted']}}}")
    parts = [plate(w, h, p)]
    y = pad
    for gi, (group, items) in enumerate(STACK):
        if gi:
            parts.append(f'<line x1="{pad}" y1="{y - row_gap:.1f}" x2="{w - pad}" y2="{y - row_gap:.1f}" '
                         f'stroke="{p["line"]}"/>')
        mid = y + tile / 2
        parts.append(f'<text class="c" x="{pad}" y="{mid - 4}">{gi + 1:02d}</text>'
                     f'<text class="g" x="{pad}" y="{mid + 14}">{K.esc(group)}</text>')
        for i, (slug, label) in enumerate(items):
            x = pad + col + i * (tile + gap)
            parts.append(f'<rect x="{x + 0.5}" y="{y + 0.5}" width="{tile - 1}" height="{tile - 1}" rx="10" '
                         f'fill="{p["panel"]}" stroke="{p["line"]}"/>')
            parts.append(glyph(slug, x + (tile - 28) / 2, y + (tile - 28) / 2, 28, p["ink"]))
            parts.append(f'<text class="t" x="{x + tile / 2}" y="{y + tile + 18}" '
                         f'text-anchor="middle">{K.esc(label)}</text>')
        y += row_h + row_gap * 2 + 1
    names = ", ".join(label for _, items in STACK for _, label in items)
    return K.svg_doc(w, h, "".join(parts), f"Стек: {names}", css)


def main():
    out = []
    for theme in K.THEMES:
        for name, slug, title, handle in CONTACTS:
            out.append(K.write(K.ASSETS / "contacts" / f"{name}-{theme}.svg", contact(theme, slug, title, handle)))
        for i, (name, label) in enumerate(SECTIONS, 1):
            out.append(K.write(K.ASSETS / "sections" / f"{name}-{theme}.svg", section(theme, i, label, len(SECTIONS))))
        out.append(K.write(K.ASSETS / f"stack-{theme}.svg", stack(theme)))
    for path in out:
        print(f"{path.relative_to(K.ROOT)}  {path.stat().st_size / 1024:.1f} KB")


if __name__ == "__main__":
    main()
